package ug.audiocity.studio;
import java.io.*;import java.nio.*;import java.nio.file.*;import java.util.*;
public class StudioTests {
 static int passed;static void check(boolean value,String message){if(!value)throw new AssertionError(message);passed++;}
 static float[] wave(int frames,double hz,double amplitude){float[] a=new float[frames*2];for(int i=0;i<frames;i++)a[2*i]=a[2*i+1]=(float)(Math.sin(i*2*Math.PI*hz/Core.RATE)*amplitude);return a;}
 static Core.Session session(float[] a){Core.Session s=new Core.Session();s.master=1;Core.Track t=new Core.Track("Test",0);t.volume=1;t.pan=-1;t.clips.add(new Core.Clip("Test",new Core.Memory(a),"",0));s.tracks.add(t);return s;}
 static float[] render(Core.Session s,int frames){float[] out=new float[frames*2],block=new float[1024];Core.Renderer r=new Core.Renderer(s);for(int pos=0;pos<frames;pos+=512){int n=Math.min(512,frames-pos);r.render(pos,n,block,false);System.arraycopy(block,0,out,pos*2,n*2);}return out;}
 static double rms(float[] a,int start,int end){double sum=0;for(int i=start;i<end;i++)sum+=a[2*i]*a[2*i];return Math.sqrt(sum/(end-start));}
 public static void main(String[] args)throws Exception {
  float[] silence=render(session(new float[2000]),1000);check(rms(silence,0,1000)==0,"Silence must stay silent");
  float[] constant=new float[2000];Arrays.fill(constant,.1f);Core.Session placed=session(constant);Core.Clip c=placed.tracks.get(0).clips.get(0);c.start=100;c.offset=10;c.length=500;float[] placedOut=render(placed,800);check(placedOut[99*2]==0&&Math.abs(placedOut[100*2]-.1)<1e-6&&placedOut[600*2]==0,"Clip placement and trimmed length");check(placedOut[201]==0,"Hard left pan has no right-channel signal");
  Core.Session muted=session(constant);muted.tracks.get(0).mute=true;check(rms(render(muted,1000),0,1000)==0,"Mute");
  Core.Session solo=session(constant);Core.Track second=new Core.Track("Silent solo",0);second.solo=true;solo.tracks.add(second);check(rms(render(solo,1000),0,1000)==0,"Solo excludes other tracks");
  Core.Session original=session(wave(16000,300,.1));Core.Session split=original.copy();Core.Clip first=split.tracks.get(0).clips.get(0),right=first.copy();first.length=8000;right.start=8000;right.offset=8000;right.length=8000;split.tracks.get(0).clips.add(right);float[] a=render(original,16000),b=render(split,16000);double diff=0;for(int i=0;i<a.length;i++)diff=Math.max(diff,Math.abs(a[i]-b[i]));check(diff<1e-7,"Non-destructive split must preserve samples");
  Core.Session eq=session(wave(Core.RATE,60,.05));double dry=rms(render(eq,Core.RATE),12000,40000);eq.tracks.get(0).fx.low=12;check(rms(render(eq,Core.RATE),12000,40000)>dry*2,"Low shelf boosts a low-frequency tone");
  Core.Session comp=session(wave(Core.RATE,400,.4));double clean=rms(render(comp,Core.RATE),12000,40000);comp.tracks.get(0).fx.comp=true;comp.tracks.get(0).fx.threshold=-30;comp.tracks.get(0).fx.ratio=6;check(rms(render(comp,Core.RATE),12000,40000)<clean*.4,"Compression reduces sustained loud signal");
  Core.Session gate=session(wave(Core.RATE,400,.0001));gate.tracks.get(0).fx.gate=true;check(rms(render(gate,Core.RATE),30000,40000)<.0000001,"Gate closes on quiet signal");
  Core.Session de=session(wave(Core.RATE,10000,.3));double high=rms(render(de,Core.RATE),12000,40000);de.tracks.get(0).fx.deess=true;de.tracks.get(0).fx.deessAmount=1;check(rms(render(de,Core.RATE),12000,40000)<high*.9,"De-esser reduces high-frequency energy");
  float[] impulse=new float[Core.RATE*2];impulse[0]=impulse[1]=.2f;Core.Session delay=session(impulse);delay.tracks.get(0).fx.delay=true;delay.tracks.get(0).fx.delayMix=.5;float[] echo=render(delay,Core.RATE);check(Math.abs(echo[14400*2])>.05,"Eighth-note delay has an echo at 300 ms / 100 BPM");
  Core.Session room=session(impulse);room.tracks.get(0).fx.room=true;room.tracks.get(0).fx.roomMix=.6;check(rms(render(room,Core.RATE),1000,10000)>0,"Room reverb produces a tail");
  Core.Session drive=session(wave(Core.RATE,300,.1));float[] bypass=render(drive,Core.RATE);drive.tracks.get(0).fx.sat=true;drive.tracks.get(0).fx.drive=6;float[] saturated=render(drive,Core.RATE);check(Math.abs(rms(saturated,10000,20000)-rms(bypass,10000,20000))>.01,"Saturation affects samples");
  Core.Session hot=session(wave(Core.RATE,100,8));Core.Track t=hot.tracks.get(0);t.fx.low=12;t.fx.mid=12;t.fx.high=12;t.fx.comp=true;t.fx.deess=true;t.fx.sat=true;t.fx.drive=6;t.fx.delay=true;t.fx.room=true;float[] limited=render(hot,Core.RATE);boolean safe=true;for(float sample:limited)if(!Float.isFinite(sample)||Math.abs(sample)>.891251)safe=false;check(safe,"Full effects chain remains finite and below sample-peak ceiling");
  Core.Session copy=hot.copy();copy.tracks.get(0).fx.low=-12;copy.tracks.get(0).clips.get(0).start=500;check(hot.tracks.get(0).fx.low==12&&hot.tracks.get(0).clips.get(0).start==0,"Undo snapshots isolate edits");
  File temp=Files.createTempDirectory("city-studio-tests").toFile();Core.Clip disk=AudioIO.store(temp,wave(10000,440,.2),"Tone",0);check(disk.source.frames()==10000&&Math.abs(disk.source.sample(200,0)-wave(201,440,.2)[400])<1e-7,"Disk PCM source round-trip");
  Core.Session export=session(wave(4800,440,.2));ByteArrayOutputStream bytes=new ByteArrayOutputStream();AudioIO.wav(bytes,export);byte[] wav=bytes.toByteArray();ByteBuffer header=ByteBuffer.wrap(wav).order(ByteOrder.LITTLE_ENDIAN);check(new String(wav,0,4,"US-ASCII").equals("RIFF")&&header.getInt(24)==48000&&header.getShort(22)==2&&header.getShort(34)==16,"WAV has valid stereo 48 kHz / 16-bit header");check(header.getInt(40)==(4800+Core.RATE*3)*4&&wav.length==header.getInt(40)+44,"WAV frame count and three-second FX tail");
  try(FileOutputStream out=new FileOutputStream(args.length>0?args[0]:"test-mix.wav")){out.write(wav);}
  Core.Session demo=new Core.Session();demo.master=.8;boolean[][] steps=new boolean[3][16];for(int i=0;i<16;i+=2)steps[2][i]=true;steps[0][0]=steps[0][8]=true;steps[1][4]=steps[1][12]=true;float[] drums=Core.drumPattern(100,steps,4);for(int i=0;i<8;i++){Core.Track tr=new Core.Track("Bench "+i,0);tr.fx.room=tr.fx.delay=tr.fx.comp=tr.fx.deess=tr.fx.sat=true;tr.clips.add(new Core.Clip("Drums",new Core.Memory(drums),"",0));demo.tracks.add(tr);}long begin=System.nanoTime();render(demo,Core.RATE*4);double seconds=(System.nanoTime()-begin)/1e9;System.out.printf(Locale.US,"%d checks passed. Eight-track DSP processed 4 seconds in %.3f seconds on this host.%n",passed,seconds);
 }
}
